// Surface ramp selection (0-25)
import { TokenSelect } from '@/lib/designsystem';
import { useState } from 'react';

function SurfaceRampSelect() {
  const [surfaceIndex, setSurfaceIndex] = useState('20');

  return (
    <TokenSelect
      id="surface-color"
      label="Surface Color"
      tokenCategory="surface-ramp"
      value={surfaceIndex}
      onChange={setSurfaceIndex}
      helperText="Select a surface ramp index (0-25)"
    />
  );
}
