```tsx
// Text color selection with validation
import { TokenSelect } from '@/lib/designsystem';
import { useState } from 'react';

function TextColorSelect() {
  const [textColor, setTextColor] = useState('');
  const [touched, setTouched] = useState(false);

  return (
    <TokenSelect
      id="text-color"
      label="Text Color"
      tokenCategory="text"
      value={textColor}
      onChange={setTextColor}
      onBlur={() => setTouched(true)}
      error={!textColor ? 'Text color is required' : undefined}
      touched={touched}
      required
    />
  );
}
```

