// Custom token options
import { TokenSelect } from '@/lib/designsystem';
import { useState } from 'react';

function CustomTokenSelect() {
  const [theme, setTheme] = useState('light');

  const customOptions = [
    { value: 'light', label: 'Light Theme', cssVar: 'var(--color-surface-25)' },
    { value: 'dark', label: 'Dark Theme', cssVar: 'var(--color-surface-0)' },
    { value: 'brand', label: 'Brand Theme', cssVar: 'var(--color-primary)' },
  ];

  return (
    <TokenSelect
      id="theme"
      label="Theme"
      tokenCategory="surface-ramp" // Ignored when options provided
      options={customOptions}
      value={theme}
      onChange={setTheme}
    />
  );
}
```
